  '--dsw-alias-state-business-tertiary': (p) => tint(p, p.fg.blue, 0.85),
  '--dsw-alias-state-error-primary': (p) => p.fg.red,
  '--dsw-alias-state-error-secondary': (p) => lift(p, p.fg.red, 0.25),
  '--dsw-alias-state-idle-primary': (p) => p.fg.grey2,
